"""Build the bilingual portfolio from curated content and shared assets."""
from pathlib import Path
from html import escape
from urllib.parse import quote
import json
import shutil

BASE = Path(__file__).resolve().parent
OUT = BASE / 'dist'
CONTENT = json.loads((BASE / 'content.json').read_text())
PROJECTS = CONTENT['PROJECTS']
INSIGHTS = CONTENT['INSIGHTS']
EMAIL = 'emmanuelakounna@gmail.com'
LINKEDIN = 'https://www.linkedin.com/in/akounna'
ORIGIN = 'https://hugues-emmanuel-akounna.emmanuelakounna.chatgpt.site'
NAV = [('', 'Accueil', 'Home'), ('apropos', 'Parcours', 'About'), ('expertises', 'Compétences', 'Expertise'), ('projets', 'Projets', 'Projects'), ('publications', 'Publications', 'Writing'), ('ressources', 'Ressources', 'Resources'), ('services', 'Services', 'Services')]
TAGS = {'Tous':'All', 'Économie':'Economics', 'Données':'Data', 'Développement':'Development', 'Finance':'Finance', 'Agriculture':'Agriculture', 'Numérique':'Digital', 'IA':'AI'}


def tr(lang, fr, en):
    return en if lang == 'en' else fr


def path(lang, route=''):
    return '/' + ('en/' if lang == 'en' else '') + (route.strip('/') + '/' if route else '')


def txt(lang, item, key):
    return item[key + '_en'] if lang == 'en' else item[key]


def tag(lang, value):
    return TAGS.get(value, value) if lang == 'en' else value


def esc(value):
    return escape(str(value), quote=True)


def link(href, label, cls='text-link'):
    return f'<a class="{cls}" href="{esc(href)}">{escape(label)} <span aria-hidden="true">↗</span></a>'


def eyebrow(label):
    return f'<p class="eyebrow"><span aria-hidden="true"></span>{escape(label)}</p>'


def tags(lang, values):
    return '<div class="tags">' + ''.join(f'<span>{escape(tag(lang,t))}</span>' for t in values) + '</div>'


def editorial_image(kind, index=0, eager=False):
    """Decorative illustrations: no photograph is presented as project evidence."""
    names = ['city', 'data', 'agriculture', 'agriculture'] if kind == 'projects' else ['city', 'agriculture', 'data']
    name = names[index % len(names)]
    priority = 'fetchpriority="high"' if eager else 'loading="lazy"'
    return f'<img src="/assets/images/{name}-editorial.webp" alt="" width="1536" height="1024" decoding="async" {priority}>'


def pagehead(lang, label, title, desc):
    return f'<section class="pagehead wrap">{eyebrow(label)}<h1>{title}</h1><p class="lead">{escape(desc)}</p></section>'


def cta(lang):
    return f'''<section class="cta"><div class="wrap cta-inner"><div>{eyebrow(tr(lang,'Construisons ensemble','Let’s work together'))}<h2>{tr(lang,'Une question.<br>Un terrain commun.','A question.<br>Common ground.')}</h2><p>{tr(lang,'Étude économique, analyse de données ou projet de développement : parlons de ce que vous souhaitez éclairer.','An economic study, data analysis or development project: let’s discuss what you need to understand.')}</p></div>{link(path(lang,'contact'),tr(lang,'Proposer une collaboration','Discuss a collaboration'),'btn btn-lime')}</div></section>'''


def layout(lang, route, title, description, body):
    active = route.split('/')[0]
    other = 'en' if lang == 'fr' else 'fr'
    nav = ''.join(f'<a class="nav-link {"active" if s == active else ""}" href="{path(lang,s)}" {"aria-current=page" if s == active else ""}>{en if lang == "en" else fr}</a>' for s,fr,en in NAV)
    switch = f'<a class="lang-switch" href="{path(other,route)}" lang="{other}" aria-label="{tr(lang,"Read this page in English","Lire cette page en français")}"><span {"class=selected" if lang=="fr" else ""}>FR</span><span aria-hidden="true">/</span><span {"class=selected" if lang=="en" else ""}>EN</span></a>'
    return f'''<!doctype html>
<html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#142824"><meta name="robots" content="noindex,nofollow"><title>{escape(title)} — Hugues Emmanuel Akounna</title><meta name="description" content="{esc(description)}"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="alternate" hreflang="fr" href="{ORIGIN}{path('fr',route)}"><link rel="alternate" hreflang="en" href="{ORIGIN}{path('en',route)}"><link rel="stylesheet" href="/assets/style.css"><link rel="stylesheet" href="/assets/premium.css"><script defer src="/assets/site.js"></script></head>
<body class="page-{active or 'home'}"><a class="skip" href="#main">{tr(lang,'Aller au contenu','Skip to content')}</a>
<header class="site-header"><div class="header-inner"><a class="brand" href="{path(lang)}" aria-label="Hugues Emmanuel Akounna — {tr(lang,'accueil','home')}"><span class="brand-monogram" aria-hidden="true">h<span>.</span>a</span><span class="brand-name">Hugues Emmanuel<br><strong>Akounna</strong></span></a><nav class="nav" id="site-nav" aria-label="{tr(lang,'Navigation principale','Main navigation')}">{nav}<a class="nav-mobile-contact" href="{path(lang,'contact')}">{tr(lang,'Collaborer','Collaborate')} ↗</a></nav><div class="header-tools">{switch}{link(path(lang,'contact'),tr(lang,'Collaborer','Collaborate'),'header-contact')}<button class="menu-toggle" type="button" aria-expanded="false" aria-controls="site-nav"><span>Menu</span><span class="menu-icon" aria-hidden="true"><i></i><i></i></span></button></div></div></header>
<main id="main">{body}</main>
<footer class="footer"><div class="wrap footer-grid"><div class="footer-intro"><a class="footer-brand" href="{path(lang)}">Hugues Emmanuel<br>Akounna<span>.</span></a><p>{tr(lang,'Économie appliquée. Données. Développement.<br>Un ancrage ouest-africain, une perspective internationale.','Applied economics. Data. Development.<br>A West African foundation, an international perspective.')}</p><span class="location"><span aria-hidden="true">◎</span> Cotonou, {tr(lang,'Bénin','Benin')}</span></div><div><span class="footer-label">{tr(lang,'Explorer','Explore')}</span><a href="{path(lang,'projets')}">{tr(lang,'Projets','Projects')}</a><a href="{path(lang,'publications')}">{tr(lang,'Publications & notes','Writing & notes')}</a><a href="{path(lang,'ressources')}">{tr(lang,'Ressources','Resources')}</a></div><div><span class="footer-label">{tr(lang,'Faire connaissance','Get to know me')}</span><a href="{path(lang,'apropos')}">{tr(lang,'Mon parcours','My background')}</a><a href="{path(lang,'expertises')}">{tr(lang,'Compétences','Expertise')}</a><a href="{path(lang,'services')}">{tr(lang,'Services','Services')}</a></div><div><span class="footer-label">{tr(lang,'Échanger','Connect')}</span><a href="mailto:{EMAIL}">Email ↗</a><a href="{LINKEDIN}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="{path(lang,'contact')}">{tr(lang,'Contact & collaboration','Contact & collaboration')}</a></div></div><div class="wrap foot-bottom"><span>© 2026 Hugues Emmanuel Akounna</span><span>{tr(lang,'Recherche appliquée · regard ouvert · conclusions mesurées','Applied research · open perspective · measured conclusions')}</span><a href="#main">{tr(lang,'Retour en haut','Back to top')} ↑</a></div></footer></body></html>'''


def visual(lang):
    labels = tr(lang,['Économie','Données','Développement','Finance','IA & numérique'],['Economics','Data','Development','Finance','AI & digital'])
    return f'''<div class="research-visual">{editorial_image('projects', 0, eager=True)}<div class="visual-top"><span>{tr(lang,'Mon champ de recherche','My research landscape')}</span><span>01—05</span></div><div class="orbit" aria-hidden="true"><div class="orbit-mark">✳</div>{''.join(f'<span class="orbit-label">{label}</span>' for label in labels)}</div><div class="visual-bottom"><span>{tr(lang,'Observer les liens.<br>Comprendre les contextes.','Observe connections.<br>Understand contexts.')}</span><span class="visual-star" aria-hidden="true">↗</span></div></div>'''


def card(lang, item, kind, index=0):
    route = 'projets' if kind=='projects' else 'publications'
    title = txt(lang,item,'title'); summary = txt(lang,item,'summary')
    searchable = ' '.join([title,summary,txt(lang,item,'kind'),item['year'],*(tag(lang,t) for t in item['tags'])])
    type_key = ('research' if index < 3 else 'field') if kind == 'projects' else ('research' if index == 0 else 'methods')
    reading = max(1,round(len(' '.join(txt(lang,item,'paragraphs')).split())/180)) if kind != 'projects' else None
    return f'''<article class="work-card filter-item" data-tags="{esc('|'.join(item['tags']))}" data-search="{esc(searchable)}" data-year="{item['year']}" data-type="{type_key}"><div class="card-meta"><span>{item['year']} / {index+1:02d}</span><span class="card-type">{escape(txt(lang,item,'kind'))}</span></div><div class="card-art art-{index%4}" aria-hidden="true">{editorial_image(kind,index)}<span>{tr(lang,['TRANSFORMATION','FINANCE','AGRICULTURE','TERRAIN'][index%4],['TRANSFORMATION','FINANCE','AGRICULTURE','FIELDWORK'][index%4]) if kind=='projects' else tr(lang,['RECHERCHE','MÉTHODE','INTELLIGENCE'][index%3],['RESEARCH','METHOD','INTELLIGENCE'][index%3])}</span><i></i><b>{'↗' if kind=='projects' else 'Aa'}</b></div><div class="card-body"><h3><a href="{path(lang,route+'/'+item['slug'])}">{escape(title)}</a></h3><p>{escape(summary)}</p><div class="card-foot">{tags(lang,item['tags'])}{link(path(lang,route+'/'+item['slug']),tr(lang,'Voir le projet','View project') if kind=='projects' else tr(lang,'Lire la note','Read note'))}</div></div>{f'<span class="reading-time">{reading} min {tr(lang,"de lecture","read")}</span>' if reading else ''}</article>'''


def filters(lang, items, kind):
    available = ['Tous'] + [t for t in TAGS if t != 'Tous' and any(t in p['tags'] for p in items)]
    buttons=''.join(f'<button type="button" class="filter-btn {"selected" if i==0 else ""}" data-filter="{esc(t)}" aria-pressed="{"true" if i==0 else "false"}">{escape(tag(lang,t))}</button>' for i,t in enumerate(available))
    options = [('all',tr(lang,'Tous les formats','All formats')),('research',tr(lang,'Recherche','Research')),('field',tr(lang,'Terrain','Fieldwork'))] if kind=='projects' else [('all',tr(lang,'Tous les formats','All formats')),('research',tr(lang,'Note de recherche','Research note')),('methods',tr(lang,'Méthode & pratique','Method & practice'))]
    opts=''.join(f'<option value="{v}">{label}</option>' for v,label in options)
    return f'''<section class="wrap collection" data-filter-root><div class="filter-heading"><h2>{tr(lang,'Explorer les travaux','Explore the work')}</h2><span class="filter-count" aria-live="polite">{len(items)} {tr(lang,'résultats','results')}</span></div><div class="filter-buttons" role="group" aria-label="{tr(lang,'Filtrer par thème','Filter by topic')}">{buttons}</div><div class="search-row"><label class="search-label"><span class="search-icon" aria-hidden="true">⌕</span><span class="sr-only">{tr(lang,'Rechercher un sujet, une méthode, un mot-clé','Search a topic, method or keyword')}</span><input type="search" class="filter-search" placeholder="{tr(lang,'Rechercher un sujet, une méthode…','Search a topic or method…')}"></label><label class="select-label"><span>{tr(lang,'Format','Format')}</span><select class="filter-type">{opts}</select></label><label class="select-label"><span>{tr(lang,'Trier','Sort')}</span><select class="filter-sort"><option value="newest">{tr(lang,'Plus récents','Newest first')}</option><option value="oldest">{tr(lang,'Plus anciens','Oldest first')}</option><option value="title">{tr(lang,'Titre A–Z','Title A–Z')}</option></select></label></div><noscript><p class="article-note">{tr(lang,'Tous les travaux sont accessibles ci-dessous. Activez JavaScript pour utiliser les filtres.','All work is available below. Enable JavaScript to use the filters.')}</p></noscript><div class="cards-grid">{''.join(card(lang,p,kind,i) for i,p in enumerate(items))}</div><div class="empty-state" hidden><span aria-hidden="true">⌕</span><h3>{tr(lang,'Aucun résultat pour ces critères.','No matches for these filters.')}</h3><p>{tr(lang,'Essayez un autre thème ou un mot-clé plus court.','Try another topic or a shorter keyword.')}</p><button type="button" class="reset-filters btn btn-dark">{tr(lang,'Réinitialiser les filtres','Reset filters')} ↗</button></div></section>'''


def home(lang):
    hero=f'''<section class="hero wrap"><div class="hero-grid"><div class="hero-copy">{eyebrow(tr(lang,'Économie appliquée · Afrique & international','Applied economics · Africa & beyond'))}<h1>{tr(lang,'Comprendre<br>les économies.<br><em>Éclairer les choix.</em>','Understand<br>economies.<br><em>Inform decisions.</em>')}</h1><p class="hero-intro">{tr(lang,'Je suis Hugues Emmanuel Akounna. Je relie recherche économique, analyse de données et enjeux de développement pour rendre les questions complexes plus lisibles.','I am Hugues Emmanuel Akounna. I connect economic research, data analysis and development challenges to make complex questions easier to understand.')}</p><div class="hero-actions">{link(path(lang,'projets'),tr(lang,'Explorer mes travaux','Explore my work'),'btn btn-dark')}{link(path(lang,'apropos'),tr(lang,'Faire connaissance','Get to know me'))}</div><p class="hero-location"><span class="status-dot" aria-hidden="true"></span>{tr(lang,'Basé au Bénin · ouvert aux collaborations internationales','Based in Benin · open to international collaboration')}</p></div>{visual(lang)}</div></section>'''
    strip=f'''<div class="scope-strip"><div class="wrap"><span>{tr(lang,'Les questions qui me guident','Questions that guide me')}</span><p>{tr(lang,'Économie','Economics')}<i>+</i>{tr(lang,'Données','Data')}<i>+</i>{tr(lang,'Développement','Development')}<i>+</i>{tr(lang,'IA','AI')}<i>+</i>Finance</p></div></div>'''
    featured=f'''<section class="section wrap"><div class="section-heading"><div>{eyebrow(tr(lang,'01 / Recherche à la une','01 / Featured research'))}<h2>{tr(lang,'Le numérique transforme-t-il<br>les économies ?','Does digital adoption<br>reshape economies?')}</h2></div>{link(path(lang,'projets'),tr(lang,'Tous les projets','All projects'))}</div><a class="featured" href="{path(lang,'projets/digitalisation-cedeao')}"><div class="feature-atlas">{editorial_image("projects",0)}<div class="atlas-top"><span>{tr(lang,'Terrain d’étude','Research scope')}</span><span>CEDEAO / ECOWAS</span></div><div class="atlas-big">15<span>{tr(lang,'économies','economies')}</span></div><div class="country-grid">{''.join(f'<span>{x}</span>' for x in ['BEN','BFA','CPV','CIV','GMB','GHA','GIN','GNB','LBR','MLI','NER','NGA','SEN','SLE','TGO'])}</div><div class="atlas-bottom"><strong>2000—2023</strong><span>{tr(lang,'Panel de pays','Country panel')}</span></div></div><div class="feature-copy"><span class="status-badge">{tr(lang,'Mémoire de master · en révision','Master’s thesis · under review')}</span><h3>{escape(txt(lang,PROJECTS[0],'title'))}</h3><p>{escape(txt(lang,PROJECTS[0],'summary'))}</p><div class="feature-points"><span>01 — {tr(lang,'Valeur ajoutée industrielle','Industrial value added')}</span><span>02 — {tr(lang,'Diversification des exportations','Export diversification')}</span></div><span class="text-link">{tr(lang,'Découvrir la question et la démarche','Explore the question and approach')} <span aria-hidden="true">↗</span></span></div></a></section>'''
    domains=[('economie','01',tr(lang,'Économie & développement','Economics & development'),tr(lang,'Trajectoires productives, agriculture et politiques publiques.','Productive change, agriculture and public policy.')),('donnees','02',tr(lang,'Données & économétrie','Data & econometrics'),tr(lang,'Des indicateurs documentés aux analyses reproductibles.','From documented indicators to reproducible analysis.')),('frontieres','03',tr(lang,'Finance, IA & numérique','Finance, AI & digital'),tr(lang,'Étudier les transformations et les usages émergents.','Studying transformation and emerging uses.'))]
    areas=f'''<section class="section band"><div class="wrap"><div class="section-heading"><div>{eyebrow(tr(lang,'02 / Domaines de travail','02 / Areas of work'))}<h2>{tr(lang,'La méthode au centre.<br>Le contexte toujours en vue.','Methods at the centre.<br>Context always in view.')}</h2></div>{link(path(lang,'expertises'),tr(lang,'Mes compétences','My expertise'))}</div><div class="topic-grid">{''.join(f'<a href="{path(lang,"expertises")}#{id}"><span class="topic-num">{n}</span><h3>{title}</h3><p>{desc}</p><span class="topic-arrow" aria-hidden="true">↗</span></a>' for id,n,title,desc in domains)}</div></div></section>'''
    selected=f'''<section class="section wrap"><div class="section-heading"><div>{eyebrow(tr(lang,'03 / Sur le terrain & dans les données','03 / In the field & in the data'))}<h2>{tr(lang,'Des questions concrètes.<br>Des démarches à explorer.','Real questions.<br>Approaches to explore.')}</h2></div>{link(path(lang,'projets'),tr(lang,'Explorer les projets','Explore projects'))}</div><div class="cards-grid">{card(lang,PROJECTS[2],'projects',2)}{card(lang,PROJECTS[1],'projects',1)}</div></section>'''
    notes=f'''<section class="section band"><div class="wrap"><div class="section-heading"><div>{eyebrow(tr(lang,'04 / Publications & notes','04 / Writing & notes'))}<h2>{tr(lang,'Partager une lecture.<br>Ouvrir la discussion.','Share a perspective.<br>Start a conversation.')}</h2></div>{link(path(lang,'publications'),tr(lang,'Toutes les notes','All writing'))}</div><div class="notes-list">{''.join(f'<a href="{path(lang,"publications/"+p["slug"])}"><span class="note-thumb" aria-hidden="true">{editorial_image("insights",i)}</span><span class="note-num">{i+1:02d}</span><div><span class="card-meta">{escape(txt(lang,p,"kind"))}</span><h3>{escape(txt(lang,p,"title"))}</h3></div><span class="note-arrow" aria-hidden="true">↗</span></a>' for i,p in enumerate(INSIGHTS))}</div></div></section>'''
    return hero+strip+featured+areas+selected+notes+cta(lang)


def about(lang):
    intro=pagehead(lang,tr(lang,'Parcours & approche','Background & approach'),tr(lang,'Un regard situé.<br><em>Une ambition ouverte.</em>','A rooted perspective.<br><em>An open ambition.</em>'),tr(lang,'Hugues Emmanuel Akounna, économiste en formation à l’Université d’Abomey-Calavi. Mon travail relie recherche appliquée, méthodes quantitatives et enjeux de développement.','Hugues Emmanuel Akounna, an emerging economist at the Université d’Abomey-Calavi. My work connects applied research, quantitative methods and development challenges.'))
    timeline=[('2024—2026',tr(lang,'Master 2 · Économie appliquée et politiques de développement','Master’s · Applied economics and development policy'),tr(lang,'Université d’Abomey-Calavi. Mémoire en révision, soutenance à préparer.','Université d’Abomey-Calavi. Thesis under review, defence to prepare.')),('2023',tr(lang,'Licence · Économie et gestion des exploitations agricoles','Undergraduate degree · Agricultural economics and farm management'),tr(lang,'Université d’Abomey-Calavi. Mémoire sur l’irrigation et la sécurité alimentaire des maraîchers.','Université d’Abomey-Calavi. Dissertation on irrigation and food security among market gardeners.')),('2022—2023',tr(lang,'Stage · Statistiques agricoles & suivi','Internship · Agricultural statistics & monitoring'),tr(lang,'SESSEC, DDAEP Zou. Participation à la collecte, au traitement des données et au suivi des indicateurs agricoles.','SESSEC, DDAEP Zou. Contributed to data collection, processing and agricultural indicator monitoring.'))]
    body=f'''<section class="wrap split-content"><div class="prose"><h2>{tr(lang,'Comprendre avant de conclure.','Understand before concluding.')}</h2><p>{tr(lang,'La transformation des économies prend des formes différentes selon les secteurs et les territoires. Je m’intéresse à ces différences : ce que les données permettent de comprendre, les questions qu’elles laissent ouvertes et les décisions qu’elles peuvent éclairer.','Economic transformation takes different forms across sectors and places. I study those differences: what data help us understand, which questions remain open and what decisions they can inform.')}</p><p>{tr(lang,'Mon ancrage au Bénin et en Afrique de l’Ouest nourrit ma lecture des contextes. Mes travaux portent sur l’agriculture, la transformation structurelle, le développement financier et la diffusion numérique. Je souhaite contribuer à des projets de recherche et de développement en Afrique comme à l’international.','My foundation in Benin and West Africa informs how I read context. My work addresses agriculture, structural transformation, financial development and digital adoption. I seek to contribute to research and development projects in Africa and internationally.')}</p><h2>{tr(lang,'Formation & expérience','Education & experience')}</h2><div class="timeline">{''.join(f'<div><span>{year}</span><div><h3>{title}</h3><p>{desc}</p></div></div>' for year,title,desc in timeline)}</div></div><aside class="profile-card"><div class="profile-monogram" aria-hidden="true">{editorial_image("insights",2)}<span class="profile-initials">h<span>.</span>a</span></div><h2>Hugues Emmanuel<br>Akounna</h2><p>{tr(lang,'Économie · données · développement','Economics · data · development')}</p><dl><div><dt>{tr(lang,'Ancrage','Based in')}</dt><dd>Cotonou, {tr(lang,'Bénin','Benin')}</dd></div><div><dt>{tr(lang,'Outils de travail','Working tools')}</dt><dd>Stata · Excel · Office</dd></div><div><dt>{tr(lang,'Langues','Languages')}</dt><dd>{tr(lang,'Français courant<br>Anglais en progression (A2)','Fluent French<br>Developing English (A2)')}</dd></div><div><dt>{tr(lang,'Collaborations','Collaboration')}</dt><dd>{tr(lang,'Recherche, missions d’analyse & projets internationaux','Research, analytical assignments & international projects')}</dd></div></dl>{link(path(lang,'contact'),tr(lang,'Faisons connaissance','Let’s connect'),'btn btn-dark')}</aside></section>'''
    return intro+body+cta(lang)


def expertise(lang):
    blocks=[('economie','01',tr(lang,'Économie & développement','Economics & development'),tr(lang,'Transformer une question économique en une démarche d’analyse claire, avec une attention aux contextes sectoriels et institutionnels.','Turn an economic question into a clear analytical approach, with attention to sector and institutional context.'),tr(lang,['Transformation structurelle & trajectoires sectorielles','Agriculture & sécurité alimentaire','Revue de littérature & synthèse de politiques'],['Structural transformation & sector pathways','Agriculture & food security','Literature reviews & policy synthesis'])),('donnees','02',tr(lang,'Données & économétrie','Data & econometrics'),tr(lang,'Construire des indicateurs cohérents, vérifier les propriétés des données et présenter les résultats avec leurs limites.','Build consistent indicators, examine data properties and present findings with their limitations.'),tr(lang,['Nettoyage, structuration & contrôle qualité','Données de panel & diagnostics sous Stata','Tableaux, visualisations & reporting'],['Cleaning, structuring & quality checks','Panel data & diagnostics in Stata','Tables, visualisation & reporting'])),('frontieres','03',tr(lang,'Finance, IA & numérique','Finance, AI & digital'),tr(lang,'Des axes de recherche et d’apprentissage pour comprendre les changements productifs et les nouveaux outils d’analyse.','Research and learning areas for understanding productive change and new analytical tools.'),tr(lang,['Développement financier & productivité sectorielle','Diffusion des TIC & transformation productive','IA comme appui à la recherche, avec vérification humaine'],['Financial development & sector productivity','ICT adoption & productive transformation','AI as research support, with human verification']))]
    rows=''.join(f'<article id="{id}" class="expertise-row"><span class="row-num">{n}</span><div><h2>{title}</h2><p>{desc}</p><ul class="skill-list">'+''.join(f'<li>{s}</li>' for s in skills)+'</ul></div></article>' for id,n,title,desc,skills in blocks)
    tools=f'''<section class="wrap tools-section"><div class="section-heading"><div>{eyebrow(tr(lang,'De la méthode au livrable','From method to output'))}<h2>{tr(lang,'Des outils pour rendre<br>l’analyse partageable.','Tools for making<br>analysis shareable.')}</h2></div></div><div class="tool-columns"><div><h3>{tr(lang,'Analyse & données','Analysis & data')}</h3><div class="tool-tags"><span>Stata</span><span>Excel</span></div><p>{tr(lang,'Préparation des données, indicateurs, diagnostics et estimations.','Data preparation, indicators, diagnostics and estimation.')}</p></div><div><h3>{tr(lang,'Restitution & communication','Reporting & communication')}</h3><div class="tool-tags"><span>Word</span><span>PowerPoint</span><span>Adobe</span><span>Figma</span></div><p>{tr(lang,'Rapports, notes, présentations et supports visuels lisibles.','Readable reports, briefs, presentations and visual materials.')}</p></div></div></section>'''
    return pagehead(lang,tr(lang,'Compétences & axes de recherche','Expertise & research interests'),tr(lang,'Relier les disciplines.<br><em>Garder la rigueur.</em>','Connect disciplines.<br><em>Keep the rigor.</em>'),tr(lang,'Économie appliquée, analyse quantitative et communication des résultats : une pratique tournée vers les questions de développement.','Applied economics, quantitative analysis and communication of findings: a practice focused on development questions.'))+f'<section class="wrap expertise-list">{rows}</section>'+tools+cta(lang)


def detail_project(lang,p):
    idx=PROJECTS.index(p)
    sections=[('question',tr(lang,'La question de départ','The starting question'),txt(lang,p,'context')),('methode',tr(lang,'La démarche','The approach'),txt(lang,p,'method')),('lecture',tr(lang,'Lecture & limites','Interpretation & limitations'),txt(lang,p,'finding'))]
    prose=''.join(f'<section id="{id}"><span class="section-num">{i+1:02d}</span><h2>{escape(h)}</h2><p>{escape(t)}</p></section>' for i,(id,h,t) in enumerate(sections))
    aside=f'''<aside class="detail-aside"><span class="aside-label">{tr(lang,'Dans ce projet','In this project')}</span><nav aria-label="{tr(lang,'Sommaire du projet','Project contents')}">{''.join(f'<a href="#{id}">{escape(h)}</a>' for id,h,t in sections)}</nav><dl><div><dt>{tr(lang,'Année','Year')}</dt><dd>{p['year']}</dd></div><div><dt>{tr(lang,'Nature','Type')}</dt><dd>{escape(txt(lang,p,'kind'))}</dd></div></dl>{tags(lang,p['tags'])}{link(path(lang,'contact')+'?project='+quote(txt(lang,p,'title')),tr(lang,'Échanger sur ce projet','Discuss this project'),'btn btn-dark')}</aside>'''
    related=[r for r in PROJECTS if r!=p][:2]
    return f'<div class="wrap detail-breadcrumb">{link(path(lang,"projets"),tr(lang,"Tous les projets","All projects"))}<span>/ {idx+1:02d}</span></div>'+pagehead(lang,txt(lang,p,'kind'),escape(txt(lang,p,'title')),txt(lang,p,'summary'))+f'<div class="wrap detail-visual" aria-hidden="true">{editorial_image("projects",idx)}</div><section class="wrap detail-layout"><article class="article-prose">{prose}<div class="article-note"><strong>{tr(lang,"Statut du travail","Work status")}</strong><p>{escape(txt(lang,p,"status"))}</p></div></article>{aside}</section><section class="section band"><div class="wrap"><h2>{tr(lang,"Poursuivre l’exploration","Keep exploring")}</h2><div class="cards-grid">'+''.join(card(lang,r,'projects',PROJECTS.index(r)) for r in related)+'</div></div></section>'


def detail_insight(lang,p):
    paras=txt(lang,p,'paragraphs')
    read=max(1,round(len(' '.join(paras).split())/180))
    prose=''.join(f'<p>{escape(t)}</p>' for t in paras)
    return f'<div class="wrap detail-breadcrumb">{link(path(lang,"publications"),tr(lang,"Toutes les notes","All writing"))}<span>{read} min {tr(lang,"de lecture","read")}</span></div>'+pagehead(lang,txt(lang,p,'kind'),escape(txt(lang,p,'title')),txt(lang,p,'summary'))+f'''<div class="wrap detail-visual note-visual" aria-hidden="true">{editorial_image("insights",INSIGHTS.index(p))}</div><section class="wrap detail-layout"><article class="article-prose note-prose">{prose}<div class="article-note"><strong>{tr(lang,'À propos de cette note','About this note')}</strong><p>{escape(txt(lang,p,'source'))}</p></div><div class="article-end"><span>{tr(lang,'Une question ou une autre lecture ?','A question or another perspective?')}</span>{link(path(lang,'contact')+'?project='+quote(txt(lang,p,'title')),tr(lang,'Poursuivre la discussion','Continue the conversation'))}</div></article><aside class="detail-aside"><span class="aside-label">Hugues Emmanuel Akounna</span><p>{tr(lang,'Économie appliquée, données et politiques de développement.','Applied economics, data and development policy.')}</p><dl><div><dt>{tr(lang,'Année','Year')}</dt><dd>{p['year']}</dd></div><div><dt>{tr(lang,'Lecture','Reading time')}</dt><dd>{read} min</dd></div></dl>{tags(lang,p['tags'])}<hr>{link(path(lang,'publications'),tr(lang,'Explorer les notes','Explore the notes'))}</aside></section>'''+cta(lang)


def services(lang):
    data=[('01',tr(lang,'Études & recherche appliquée','Studies & applied research'),tr(lang,'Cadrer une question, réunir les sources et construire une lecture économique du problème.','Frame a question, gather sources and develop an economic reading of the problem.'),tr(lang,'Note de recherche · revue de littérature · synthèse','Research brief · literature review · synthesis')),('02',tr(lang,'Analyse de données','Data analysis'),tr(lang,'Nettoyer, documenter et analyser vos données pour produire des indicateurs et des résultats interprétables.','Clean, document and analyse your data to produce indicators and interpretable findings.'),tr(lang,'Base structurée · tableaux · script Stata · rapport','Structured data · tables · Stata script · report')),('03',tr(lang,'Suivi & reporting','Monitoring & reporting'),tr(lang,'Appuyer la définition d’indicateurs, le contrôle des données et la restitution des résultats de projet.','Support indicator design, data quality checks and reporting of project outcomes.'),tr(lang,'Tableau de suivi · fiche indicateur · synthèse','Monitoring table · indicator sheet · summary')),('04',tr(lang,'Veille & communication analytique','Research intelligence & analytical communication'),tr(lang,'Comparer les éléments disponibles et traduire une analyse technique en supports clairs pour vos équipes.','Compare available evidence and turn technical analysis into clear materials for your team.'),tr(lang,'Note stratégique · présentation · supports visuels','Strategic brief · presentation · visual materials'))]
    cards=''.join(f'<article class="service-card"><span class="row-num">{n}</span><h2>{title}</h2><p>{desc}</p><div class="service-output"><span>{tr(lang,"Livrables possibles","Possible outputs")}</span>{output}</div>{link(path(lang,"contact")+"?service="+quote(title),tr(lang,"Discuter de cette mission","Discuss this assignment"))}</article>' for n,title,desc,output in data)
    steps=[(tr(lang,'Cadrer','Scope'),tr(lang,'Question, contexte et échéance.','Question, context and timing.')),(tr(lang,'Analyser','Analyse'),tr(lang,'Données, méthode et vérifications.','Data, method and verification.')),(tr(lang,'Partager','Share'),tr(lang,'Livrable clair et limites explicites.','Clear output and explicit limitations.'))]
    return pagehead(lang,tr(lang,'Services & collaborations','Services & collaboration'),tr(lang,'Votre question.<br><em>Une démarche adaptée.</em>','Your question.<br><em>A tailored approach.</em>'),tr(lang,'Je propose un appui aux équipes de recherche, organisations de développement, institutions et entreprises, sur un périmètre défini ensemble.','I offer support to research teams, development organisations, institutions and businesses, with a scope we define together.'))+f'<section class="wrap service-grid">{cards}</section><section class="wrap process-section"><h2>{tr(lang,"Comment nous pouvons travailler","How we can work together")}</h2><div class="process-grid">'+''.join(f'<div><span>0{i+1}</span><h3>{title}</h3><p>{desc}</p></div>' for i,(title,desc) in enumerate(steps))+'</div></section>'+cta(lang)


def resources(lang):
    rows=[(tr(lang,'Comprendre le terrain','Understand the scope'),tr(lang,'Numérique & transformation productive','Digital adoption & productive change'),tr(lang,'La question du mémoire CEDEAO, son périmètre et les vérifications en cours.','The ECOWAS thesis question, its scope and checks in progress.'),'publications/numerique-transformation'),(tr(lang,'Lire les données','Read the data'),tr(lang,'Quatre questions face à un indicateur','Four questions to ask of an indicator'),tr(lang,'Couverture, définition, comparabilité et incertitude : une grille de lecture.','Coverage, definition, comparability and uncertainty: a reading guide.'),'publications/donnees-politiques'),(tr(lang,'Travailler avec l’IA','Work with AI'),tr(lang,'Organiser la recherche, vérifier les résultats','Organise research, verify results'),tr(lang,'Un cadre de pratique pour garder la maîtrise des sources et des analyses.','A practical framework for keeping control of sources and analysis.'),'publications/ia-recherche')]
    return pagehead(lang,tr(lang,'Ressources & méthodes','Resources & methods'),tr(lang,'Des repères.<br><em>Pour aller plus loin.</em>','Starting points.<br><em>For deeper thinking.</em>'),tr(lang,'Des lectures accessibles sur ce site pour comprendre une démarche et poser de meilleures questions aux données.','Accessible writing on this site to understand an approach and ask better questions of data.'))+f'<section class="wrap resource-list">'+''.join(f'<article><span class="row-num">0{i+1}</span><div><span class="card-meta">{label}</span><h2>{title}</h2><p>{desc}</p></div>{link(path(lang,route),tr(lang,"Lire la ressource","Read resource"))}</article>' for i,(label,title,desc,route) in enumerate(rows))+'</section>'+cta(lang)


def contact(lang):
    reasons=[('research',tr(lang,'Projet de recherche','Research project')),('data',tr(lang,'Analyse de données','Data analysis')),('development',tr(lang,'Projet de développement','Development project')),('opportunity',tr(lang,'Opportunité professionnelle','Professional opportunity')),('other',tr(lang,'Autre collaboration','Other collaboration'))]
    opts=''.join(f'<option value="{v}">{label}</option>' for v,label in reasons)
    return pagehead(lang,tr(lang,'Contact & collaboration','Contact & collaboration'),tr(lang,'Commençons par<br><em>votre question.</em>','Let’s start with<br><em>your question.</em>'),tr(lang,'Une mission d’analyse, une équipe à rejoindre ou un projet de recherche ? Présentez-moi votre contexte et ce que vous souhaitez construire.','An analytical assignment, a team to join or a research project? Tell me about your context and what you want to build.'))+f'''<section class="wrap contact-grid"><aside class="contact-primary"><span class="eyebrow">{tr(lang,'Écrire directement','Write directly')}</span><h2>{tr(lang,'Un premier échange,<br>tout simplement.','A first conversation,<br>simply.')}</h2><a class="email-large" href="mailto:{EMAIL}">{EMAIL} ↗</a><button class="copy-email" type="button" data-copy="{EMAIL}">{tr(lang,'Copier l’adresse','Copy address')} <span aria-hidden="true">⧉</span></button><span class="copy-status" role="status" aria-live="polite"></span><div class="contact-details"><span>◎ Cotonou, {tr(lang,'Bénin','Benin')}</span><span>{tr(lang,'À distance & à l’international','Remote & international')}</span><a href="{LINKEDIN}" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a></div></aside><div class="contact-composer"><h2>{tr(lang,'Préparer votre message','Prepare your message')}</h2><p>{tr(lang,'Quelques précisions pour démarrer sur de bonnes bases.','A few details to get the conversation started.')}</p><noscript><p class="article-note">{tr(lang,"Pour préparer un message dans ce formulaire, activez JavaScript. Vous pouvez aussi utiliser directement le lien email.","Enable JavaScript to prepare a message with this form, or use the direct email link.")}</p></noscript><form id="contact-form" data-email="{EMAIL}"><div class="form-row"><label>{tr(lang,'Votre nom','Your name')}<input name="name" autocomplete="name" required maxlength="100" placeholder="{tr(lang,'Nom et prénom','Full name')}"></label><label>{tr(lang,'Organisation','Organisation')} <span class="optional">({tr(lang,'facultatif','optional')})</span><input name="organisation" autocomplete="organization" maxlength="140" placeholder="{tr(lang,'Votre équipe ou institution','Your team or institution')}"></label></div><label>{tr(lang,'Sujet de l’échange','What is this about?')}<select name="reason">{opts}</select></label><label>{tr(lang,'Votre question ou projet','Your question or project')}<textarea name="message" required minlength="10" maxlength="5000" rows="5" placeholder="{tr(lang,'Contexte, besoin, livrable souhaité et échéance…','Context, needs, expected output and timeline…')}"></textarea></label><button type="submit" class="btn btn-dark">{tr(lang,'Préparer un email','Prepare an email')} <span aria-hidden="true">↗</span></button><p class="form-note">{tr(lang,'Ce bouton ouvre votre application de messagerie. Vous relisez et envoyez le message vous-même.','This button opens your email application. You review and send the message yourself.')}</p><p id="form-status" class="form-status" aria-live="polite"></p><div id="email-fallback" hidden><label>{tr(lang,'Message préparé','Prepared message')}<textarea id="prepared-message" readonly rows="7"></textarea></label><p>{tr(lang,'Si votre messagerie ne s’ouvre pas, copiez ce texte et envoyez-le à l’adresse indiquée.','If your email application does not open, copy this text and send it to the address shown.')}</p></div></form></div></section>'''


def write(lang, route, title, desc, body):
    dest=OUT / ('en' if lang=='en' else '') / route / 'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(layout(lang,route,title,desc,body),encoding='utf-8')


def main():
    OUT.mkdir(exist_ok=True)
    shutil.copytree(BASE/'assets',OUT/'assets',dirs_exist_ok=True)
    for lang in ('fr','en'):
        write(lang,'',tr(lang,'Économie, données & développement','Economics, data & development'),tr(lang,'Portfolio de Hugues Emmanuel Akounna : économie appliquée, données, développement, IA et finance.','Hugues Emmanuel Akounna’s portfolio: applied economics, data, development, AI and finance.'),home(lang))
        write(lang,'apropos',tr(lang,'Parcours & approche','Background & approach'),tr(lang,'Formation, expérience et approche de Hugues Emmanuel Akounna.','Education, experience and approach of Hugues Emmanuel Akounna.'),about(lang))
        write(lang,'expertises',tr(lang,'Compétences & axes de recherche','Expertise & research interests'),tr(lang,'Économie appliquée, données, économétrie, finance, numérique et IA.','Applied economics, data, econometrics, finance, digital and AI.'),expertise(lang))
        write(lang,'projets',tr(lang,'Projets','Projects'),tr(lang,'Projets de recherche et expérience de terrain : explorer les questions, les méthodes et les limites.','Research projects and field experience: explore the questions, methods and limitations.'),pagehead(lang,tr(lang,'Projets & terrain','Projects & fieldwork'),tr(lang,'Du terrain à l’analyse.<br><em>Explorer les liens.</em>','From the field to analysis.<br><em>Explore connections.</em>'),tr(lang,'Questions de recherche, méthodes et expériences : parcourez mes travaux par thème ou par format. Chaque fiche précise la nature et le statut du projet.','Research questions, methods and experience: explore my work by topic or format. Each page identifies the project’s nature and status.'))+filters(lang,PROJECTS,'projects')+cta(lang))
        for p in PROJECTS: write(lang,'projets/'+p['slug'],txt(lang,p,'title'),txt(lang,p,'summary'),detail_project(lang,p))
        write(lang,'publications',tr(lang,'Publications & notes','Writing & notes'),tr(lang,'Notes de recherche, de méthode et de pratique.','Research, methods and practice notes.'),pagehead(lang,tr(lang,'Publications & notes','Writing & notes'),tr(lang,'Une question.<br><em>Une lecture à partager.</em>','A question.<br><em>A perspective to share.</em>'),tr(lang,'Des notes de recherche, de méthode et de pratique. Leur statut est indiqué : ces textes de portfolio ne sont pas présentés comme des articles scientifiques publiés.','Research, methods and practice notes. Their status is stated: these portfolio texts are not presented as published academic articles.'))+filters(lang,INSIGHTS,'insights')+cta(lang))
        for p in INSIGHTS: write(lang,'publications/'+p['slug'],txt(lang,p,'title'),txt(lang,p,'summary'),detail_insight(lang,p))
        write(lang,'ressources',tr(lang,'Ressources & méthodes','Resources & methods'),tr(lang,'Repères accessibles pour lire les données et comprendre une démarche de recherche.','Accessible starting points for reading data and understanding a research approach.'),resources(lang))
        write(lang,'services',tr(lang,'Services & collaborations','Services & collaboration'),tr(lang,'Recherche appliquée, analyse de données, suivi et communication analytique.','Applied research, data analysis, monitoring and analytical communication.'),services(lang))
        write(lang,'contact',tr(lang,'Contact & collaboration','Contact & collaboration'),tr(lang,'Proposer une mission, un projet de recherche ou une collaboration internationale.','Discuss an assignment, research project or international collaboration.'),contact(lang))
    (OUT/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
    print(f'Built {len(list(OUT.rglob("index.html")))} bilingual pages.')


if __name__=='__main__':
    main()
